name: 'Paths Filter with Retry'
description: 'Wrapper around dorny/paths-filter that retries on failure and fails open'
inputs:
  filters:
    description: 'Path filter rules in YAML format'
    required: true
outputs:
  content:
    description: 'Whether content files changed'
    value: ${{ steps.set-outputs.outputs.content }}
  framing:
    description: 'Whether framing files changed'
    value: ${{ steps.set-outputs.outputs.framing }}
  promote:
    description: 'Whether promote files changed'
    value: ${{ steps.set-outputs.outputs.promote }}
  code:
    description: 'Whether code files changed'
    value: ${{ steps.set-outputs.outputs.code }}
  python:
    description: 'Whether python files changed'
    value: ${{ steps.set-outputs.outputs.python }}
  frontend:
    description: 'Whether frontend files changed'
    value: ${{ steps.set-outputs.outputs.frontend }}
  agent_config:
    description: 'Whether agent configuration files changed'
    value: ${{ steps.set-outputs.outputs.agent_config }}
  lesson_schema:
    description: 'Whether lesson schema files changed'
    value: ${{ steps.set-outputs.outputs.lesson_schema }}
  atlas:
    description: 'Whether atlas files changed'
    value: ${{ steps.set-outputs.outputs.atlas }}
  postmortems:
    description: 'Whether postmortems files changed'
    value: ${{ steps.set-outputs.outputs.postmortems }}
  preparation:
    description: 'Whether BIO preparation data changed'
    value: ${{ steps.set-outputs.outputs.preparation }}

runs:
  using: 'composite'
  steps:
    - name: Paths Filter (Attempt 1)
      uses: dorny/paths-filter@7b450fff21473bca461d4b92ce414b9d0420d706 # v4 — SHA-pinned per supply-chain hardening 2026-05-19
      id: filter1
      continue-on-error: true
      with:
        filters: ${{ inputs.filters }}

    - name: Sleep before retry 1
      if: steps.filter1.outcome == 'failure'
      run: sleep 5
      shell: bash

    - name: Paths Filter (Attempt 2)
      if: steps.filter1.outcome == 'failure'
      uses: dorny/paths-filter@7b450fff21473bca461d4b92ce414b9d0420d706 # v4 — SHA-pinned per supply-chain hardening 2026-05-19
      id: filter2
      continue-on-error: true
      with:
        filters: ${{ inputs.filters }}

    - name: Sleep before retry 2
      if: steps.filter1.outcome == 'failure' && steps.filter2.outcome == 'failure'
      run: sleep 15
      shell: bash

    - name: Paths Filter (Attempt 3)
      if: steps.filter1.outcome == 'failure' && steps.filter2.outcome == 'failure'
      uses: dorny/paths-filter@7b450fff21473bca461d4b92ce414b9d0420d706 # v4 — SHA-pinned per supply-chain hardening 2026-05-19
      id: filter3
      continue-on-error: true
      with:
        filters: ${{ inputs.filters }}

